    const w = this.canvas.width;
    const h = this.canvas.height;
    ctx.save();
    // Semi-transparent dark overlay
    ctx.fillStyle = 'rgba(0, 0, 0, 0.65)';
    ctx.fillRect(0, 0, w, h);
