    if (value < 1000000) {
        const k = value / 1000;
        return (k % 1 === 0 ? k.toString() : k.toFixed(1)) + 'k';
    }
    const m = value / 1000000;
    return (m % 1 === 0 ? m.toString() : m.toFixed(1)) + 'm';
